function dashboardPreRegister(d) { requireStaff(); const name = String(d && d.name || '').replace(/\s+/g, ' ').trim(); if (!name) throw new Error('חסר שם מלא');
  const phone = String(d.phone || '').replace(/[^0-9]/g, ''); if (phone.length < 9) throw new Error('חסר טלפון תקין');
  const sh = SpreadsheetApp.getActive().getSheetByName(SHEET), names = sh.getRange(FIRST, 1, ROWS, 1).getValues().map(r => String(r[0]).trim());
  if (names.indexOf(name) >= 0) throw new Error('כבר יש בלוח מתאמן בשם הזה'); const i = names.indexOf(''); if (i < 0) throw new Error('אין שורה פנויה בלוח'); const row = FIRST + i;
  sh.getRange(row, 1).setValue(name); sh.getRange(row, C['סטטוס']).setValue('ממתין לתשלום');
  sh.getRange(row, C['טלפון']).setNumberFormat('@').setValue(phone.indexOf('972') === 0 ? '0' + phone.slice(3) : (phone.charAt(0) === '0' ? phone : '0' + phone));
  if (d.email) sh.getRange(row, C['מייל']).setValue(String(d.email).trim());
  const gm = { 'ירידה במשקל': 'ירידה', 'חיטוב': 'ירידה', 'עלייה במסת שריר': 'עלייה' }; if (gm[d.goal]) sh.getRange(row, C['מטרה']).setValue(gm[d.goal]);
  setOnbState(name, { prefill: { age: String(d.age || ''), gender: String(d.gender || ''), height: String(d.height || ''), weight: String(d.weight || ''), goal: String(d.goal || '') } });
  try { CacheService.getScriptCache().removeAll(['onb']); } catch (e) {}
  return Object.assign({ name }, intakeLink_(name)); }

